from app.core.resources import display_rows

"""Import Jobs endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "import_jobs"
router = APIRouter(prefix="/import-jobs", tags=["Import Jobs"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.uploaded_by_code,
       t.filename,
       t.file_sha256,
       t.status,
       t.total_rows,
       t.successful_rows,
       t.failed_rows,
       t.finished_at,
       t.contract_version,
       t.reviewed_by_user_code,
       t.approved_at,
       t.errors,
       t.staged_rows,
       x.data AS extras
FROM import_jobs AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'import_jobs' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.uploaded_by_code,
       t.filename,
       t.file_sha256,
       t.status,
       t.total_rows,
       t.successful_rows,
       t.failed_rows,
       t.finished_at,
       t.contract_version,
       t.reviewed_by_user_code,
       t.approved_at,
       t.errors,
       t.staged_rows,
       x.data AS extras
FROM import_jobs AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'import_jobs' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO import_jobs (
    code,
    uploaded_by_code,
    filename,
    file_sha256,
    status,
    total_rows,
    successful_rows,
    failed_rows,
    finished_at,
    contract_version,
    reviewed_by_user_code,
    approved_at,
    errors,
    staged_rows
)
VALUES (
    %(code)s,
    %(uploaded_by_code)s,
    %(filename)s,
    %(file_sha256)s,
    %(status)s,
    %(total_rows)s,
    %(successful_rows)s,
    %(failed_rows)s,
    %(finished_at)s,
    COALESCE(%(contract_version)s, '2.0'::text),
    %(reviewed_by_user_code)s,
    %(approved_at)s,
    %(errors)s,
    %(staged_rows)s
)
"""

UPDATE_SQL = """
UPDATE import_jobs
SET uploaded_by_code = %(uploaded_by_code)s,
    filename = %(filename)s,
    file_sha256 = %(file_sha256)s,
    status = %(status)s,
    total_rows = %(total_rows)s,
    successful_rows = %(successful_rows)s,
    failed_rows = %(failed_rows)s,
    finished_at = %(finished_at)s,
    contract_version = %(contract_version)s,
    reviewed_by_user_code = %(reviewed_by_user_code)s,
    approved_at = %(approved_at)s,
    errors = %(errors)s,
    staged_rows = %(staged_rows)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM import_jobs
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM import_rows WHERE job_code = %(code)s) THEN 'import_rows'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return [row for row in sql.fetch_all(data, TABLE, LIST_SQL) if not row.get("deleted_at")]


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    from app.modules.documents.files.api import delete_file
    delete_file("import-workbook", code, request, user)
